def search(term,portal='robu'):
    if portal=='quartz':return 'https://quartzcomponents.com/search?q='+quote_plus(term)
    if portal=='robocraze':return 'https://robocraze.com/search?q='+quote_plus(term)
    return 'https://robu.in/?s='+quote_plus(term)+'&post_type=product'
def link(url,label='Buy / inspect'):return f'[{label}]({url})'
rows=[]
def part(project,id,qty,name,spec,cost,url,alternative,alturl,fit,stage='Base',price_status='Estimate / spending cap',image=''):
    rows.append(dict(project=project,id=id,stage=stage,quantity=qty,component=name,specification=spec,
      unit_inr=cost,line_inr=round(qty*cost,2),price_status=price_status,primary_url=url,
      alternative=alternative,alternative_url=alturl,compatibility_and_purchase_checks=fit,
      image=photos.get(image,{}).get('local_image','')))

