def table(project,stage):
 selected=[r for r in rows if r['project']==project and r['stage']==stage]
 result=['| ID / Qty | Component and required specification | Unit / line ₹ | Buy source / price evidence | Best alternative and fit implications |','|---|---|---:|---|---|']
 for r in selected:
  result.append(f"| {r['id']} / **{r['quantity']}** | **{r['component']}** — {r['specification']} | {r['unit_inr']:,.2f} / **{r['line_inr']:,.2f}** | {link(r['primary_url'])}; {r['price_status']} | {r['alternative']}; {link(r['alternative_url'],'Alternative portal')}. **Fit/check:** {r['compatibility_and_purchase_checks']} |")
 return '\n'.join(result)
